626	    /** Give out the next claim number in a fiscal year after the last given in it anywhere in the sheet's tree. */
627	    public int nextClaimNumberIn(int fiscalYear, int lastInTree) {
628	        int next = Math.max(getLastClaimNumberIn(fiscalYear), lastInTree) + 1;
629	        lastFiscalClaimNumbers.put(fiscalYear, next);
630	        return next;
631	    }
