638	    /** Set the roles that may take an action (null: the standing rule). */
639	    public void setPermission(String action, String roles) {
640	        if (roles == null) {
641	            permissions.remove(action);
642	        } else {
643	            permissions.put(action, roles);
644	        }
645	    }
646	
647	    /** Whether a role may take an action: the roles set for it, else its standing rule. */
648	    public boolean permits(String action, String role) {
649	        String roles = permissions.getOrDefault(action, STANDING_PERMISSIONS.get(action));
650	        return Arrays.asList(roles.split(",")).contains(role);
651	    }
