s=s.replace(old,'''        // A grade already in force from the date is not recorded again, so it does not hold over a grade
        // recorded later from an earlier date.
        LocalDate from = gradeFrom != null ? gradeFrom : today;
        if (!grade.equals(person.gradeOn(from))) {
            person.gradeFrom(grade, from);
        }
        Person saved = people.saveAndFlush(person);
        audited("PERSON_EDITED"''')
open(p,'w').write(s)
EOF
bin/e2e > .run/e2e-out.log 2>&1; tail -40 .run/e2e-out.log
